using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Pure and applied mathematics." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, and language studies." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Learn the fundamentals of programming using C#. Covers variables, control flow, methods, and object-oriented design.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and is the author of 'Programming Fundamentals with C#'.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 2, Title = "Data Structures & Algorithms", Code = "CS 201", Description = "In-depth study of arrays, linked lists, trees, graphs, sorting, and searching algorithms with complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm design and has published extensively on graph theory.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 3, Title = "Database Systems", Code = "CS 340", Description = "Relational database design, SQL, normalization, indexing, and transaction management.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Carol Singh", InstructorBio = "Dr. Singh spent a decade in industry at Oracle before joining academia.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
        new() { Id = 4, Title = "Calculus I", Code = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park is a passionate educator known for making calculus accessible and engaging.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
        new() { Id = 5, Title = "Linear Algebra", Code = "MATH 220", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Eva Rossi", InstructorBio = "Dr. Rossi's research focuses on numerical linear algebra and scientific computing.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 6, Title = "General Physics I", Code = "PHYS 101", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM + Lab Fri 2:00–4:50 PM", InstructorName = "Dr. Frank Yamamoto", InstructorBio = "Dr. Yamamoto's research interests include condensed matter physics and science pedagogy.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
        new() { Id = 7, Title = "Quantum Mechanics", Code = "PHYS 301", Description = "Wave functions, Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Grace Okafor", InstructorBio = "Dr. Okafor is an award-winning researcher in quantum information science.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 8, Title = "Creative Writing", Code = "ENG 205", Description = "Workshop-based course focusing on fiction and poetry. Students produce a portfolio of original work.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Prof. Hannah Lee", InstructorBio = "Prof. Lee is a published novelist and poet whose work has appeared in The New Yorker.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
        new() { Id = 9, Title = "American Literature", Code = "ENG 310", Description = "Survey of major American literary works from the colonial period to the present.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Isaac Washington", InstructorBio = "Dr. Washington specializes in 20th-century American fiction and African American literature.", DepartmentId = 4, DepartmentName = "English", IsFeatured = true },
        new() { Id = 10, Title = "World History to 1500", Code = "HIST 101", Description = "Global civilizations from prehistory through the Renaissance. Explores political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Julia Andersen", InstructorBio = "Dr. Andersen is an archaeologist and historian specializing in ancient Mediterranean cultures.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
    ];

    public IReadOnlyList<Department> GetDepartments() => Departments;

    public Department? GetDepartment(int id) => Departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() => Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => Courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetAllCourses() => Courses;

    public IReadOnlyList<Course> SearchCourses(string? search, int? departmentId)
    {
        var query = Courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

